/* Row of the 23-row profile for row y of a button h rows tall: the top two
 * and bottom three rows keep their place; the gradient stretches between. */
static int stretch_row(int y, int h) {
    if (y < 3)
        return y;
    if (y >= h - 4)
        return 23 - (h - y);
    double t = (y - 3) / (double)XD_MAX(h - 8, 1);
    double v = round(3 + t * (23 - 8));
    return (int)v;
}

/* Lighten (hot) or darken (pressed) the face, leaving border and ring. */
static uint32_t face_state(uint32_t c, uint8_t state, uint32_t shade) {
    bool face = (c & 0xFF) > 0xB0 && ((c >> 16) & 0xFF) > 0xB0;
    if (!face)
        return c;
    if (state & XD_STATE_PRESSED)
        return mix(c, 0xFF000000u | shade, 0.55);
    return c;
}

void xd_luna_draw_button(const xd_theme *t, cairo_t *cr, xd_rect r, uint8_t state,
                         const char *label) {
    bool disabled = state & XD_STATE_DISABLED;
    /* Blue's button, or Silver's: the same shape with a cooler face. */
    bool sv = silver(t);
    const uint32_t (*left)[23] = sv ? luna_silver_button_left : button_left;
    const uint32_t (*right)[23] = sv ? luna_silver_button_right : button_right;
    const uint32_t *mid = sv ? luna_silver_button_mid : button_mid;
    uint32_t off_border = sv ? luna_silver_button_disabled_border : 0xFFC9C7BAu;
    uint32_t off_face = sv ? luna_silver_button_disabled_face : 0xFFF5F4EAu;
    image im;
    int w = logical(t, r.w), h = logical(t, r.h);
    if (image_new(&im, w, h)) {
        for (int y = 0; y < h; y++) {
            int ry = stretch_row(y, h);
            for (int x = 0; x < w; x++) {
                uint32_t c;
                if (x < 5)
                    c = left[x][ry];
                else if (x >= w - 5)
                    c = right[x - (w - 5)][ry];
                else
                    c = mid[ry];
                c |= 0xFF000000u;
                if (disabled) {
                    /* Flat face and a grey border: blue border pixels (and
                     * their anti-aliased corners) become grey by how dark
                     * they are; the face becomes flat. */
                    uint32_t r8 = (c >> 16) & 0xFF, b8 = c & 0xFF;
                    bool ring = x == 0 || y == 0 || x == w - 1 || y == h - 1;
                    if (b8 > r8 + 24)
                        c = mix(off_border, off_face, r8 / 255.0 * 1.2 > 1 ? 1 : r8 / 255.0 * 1.2);
                    else if (!ring)
                        c = off_face;
                } else {
                    c = face_state(c, state, mid[20]);
                }
                put(&im, x, y, c);
            }
        }
        /* Hover: an orange inner ring; focus or default: a blue one. */
        uint32_t ring_top = 0, ring_bottom = 0;
        if (!disabled && (state & XD_STATE_HOT) && !(state & XD_STATE_PRESSED)) {
            ring_top = 0xFFFFF0CFu;
            ring_bottom = 0xFFE59700u;
        } else if (!disabled && (state & (XD_STATE_FOCUSED | XD_STATE_DEFAULT))) {
            ring_top = 0xFFCEE7FFu;
            ring_bottom = 0xFF6982EEu;
        }
        if (ring_top != 0) {
            for (int y = 2; y < h - 2; y++) {
                double k = (y - 2) / (double)XD_MAX(h - 5, 1);
                uint32_t c = mix(ring_top, ring_bottom, k);
                put(&im, 2, y, c);
                put(&im, 3, y, mix(c, 0xFFFFFFFFu, 0.35));
                put(&im, w - 3, y, c);
                put(&im, w - 4, y, mix(c, 0xFFFFFFFFu, 0.35));
            }
            for (int x = 3; x < w - 3; x++) {
                put(&im, x, 2, ring_top);
                put(&im, x, h - 3, ring_bottom);
                put(&im, x, 3, mix(ring_top, 0xFFFFFFFFu, 0.35));
                put(&im, x, h - 4, mix(ring_bottom, 0xFFFFFFFFu, 0.35));
            }
        }
        image_paint(cr, &im, r);
    }
    xd_text_style st = xd_text(t, XD_FONT_MESSAGE,
                               disabled ? xd_rgba_hex(0xA1A192) : xd_sys(t, XD_COLOR_BUTTON_TEXT),
                               XD_ALIGN_CENTER);
    int dy = (state & XD_STATE_PRESSED) ? xd_tpx(t, 1) : 0;
    xd_draw_text(cr, (xd_rect){r.x + dy, r.y + dy, r.w, r.h}, label, &st);
}

/* Check box interior: a diagonal gradient, by i + j (0..20). */
static const uint32_t check_off[21] = {
    0xDCDCD7, 0xDCDCD7, 0xDCDCD7, 0xDEDED9, 0xE0E0DB, 0xE2E2DE, 0xE5E5E2,
    0xE8E8E5, 0xECECE9, 0xEFEFEC, 0xF1F1EF, 0xF3F3F1, 0xF5F5F4, 0xF7F7F6,
    0xF9F9F8, 0xFBFBFA, 0xFDFDFC, 0xFEFEFE, 0xFFFFFF, 0xFFFFFF, 0xFFFFFF,
};
static const uint32_t check_on[21] = {
    0xE2E2DD, 0xE2E2DD, 0xE2E2DD, 0xE3E3DF, 0xE5E5E1, 0xE7E7E3, 0xEAEAE6,
    0xECECE9, 0xEFEFEC, 0xF1F1EF, 0xF3F3F1, 0xF5F5F3, 0xF7F7F6, 0xF9F9F8,
    0xFAFAF9, 0xFCFCFB, 0xFDFDFD, 0xFEFEFE, 0xFFFFFF, 0xFFFFFF, 0xFFFFFF,
};
/* XP's 7x7 check mark, in the 11x11 interior from (2, 2). */
static const char *const check_mark[7] = {
    "......#", ".....##", "#...###", "##.###.", "#####..", ".###...", "..#....",
};

void xd_luna_draw_checkbox(const xd_theme *t, cairo_t *cr, xd_rect r, uint8_t state,
                           const char *label) {
    bool disabled = state & XD_STATE_DISABLED;
    bool checked = state & XD_STATE_CHECKED;
    int box = xd_tpx(t, 13);
    xd_rect b = {r.x, r.y + (r.h - box) / 2, box, box};
    image im;
    if (image_new(&im, 13, 13)) {
        for (int y = 0; y < 13; y++) {
            for (int x = 0; x < 13; x++) {
                uint32_t c;
                if (x == 0 || y == 0 || x == 12 || y == 12) {
                    c = disabled ? 0xCAC8BB : 0x1C5180;
                } else {
                    int d = (x - 1) + (y - 1);
                    c = disabled ? 0xFFFFFF : checked ? check_on[d] : check_off[d];
                    if (!disabled && (state & XD_STATE_HOT) &&
                        (x == 1 || y == 1 || x == 11 || y == 11 || x == 2 || y == 2 ||
                         x == 10 || y == 10))
                        c = mix(c | 0xFF000000u, 0xFFF8B330u, x <= 1 || y <= 1 || x >= 11 ||
                                                                      y >= 11
                                                                  ? 0.75
                                                                  : 0.4);
                    int mx = x - 3, my = y - 3;
                    if (checked && mx >= 0 && mx < 7 && my >= 0 && my < 7 &&
                        check_mark[my][mx] == '#')
                        c = disabled ? 0xCAC8BB : 0x21A121;
                }
                put(&im, x, y, c | 0xFF000000u);
            }
        }
        image_paint(cr, &im, b);
    }
    int gap = xd_tpx(t, 5);
    xd_text_style st = xd_text(t, XD_FONT_MESSAGE,
                               disabled ? xd_rgba_hex(0xA1A192) : xd_sys(t, XD_COLOR_WINDOW_TEXT),
                               XD_ALIGN_START);
    xd_draw_text(cr, (xd_rect){b.x + box + gap, r.y, r.w - box - gap, r.h}, label, &st);
}
